+    // 'resolved'/'dismissed' via finding_resolve, which mutates the stored record
+    // in place. Comparing the live status against a hardcoded 'open' therefore
+    // made every managed finding's receipt invalid the moment it was resolved,
+    // and `managed_receipt_invalid` is absent from SUPERSEDED_PASS_ISSUE_CODES,
+    // so it reached evidenceState.invalid and hard-blocked REVIEW→TEST at
+    // machine.ts BEFORE the blocking-severity filter — i.e. resolving a managed
+    // finding permanently blocked the gate regardless of its severity.
+    //
+    // Fix: exclude the mutable lifecycle status from the authorship digest on
+    // BOTH sides. Every provider-authored field (desc/severity/category/
+    // evidenceState/uncertaintyReason/files/read provenance) stays byte-bound,
+    // so tampering with real authored content is still rejected; only the
+    // host-owned lifecycle transition is permitted to move.
+    //
+    // No separate "authored status must be open" guard is needed: the provider
+    // proposal type (ManagedReviewEvidenceFindingProposal in managed-host-run.ts)
+    // has NO status field, so a provider structurally cannot author one and the
+    // old literal 'open' was describing the type, not validating input.
+    return digestCanonicalJson({
+      desc: args.evidence.finding.desc,
+      severity: args.evidence.finding.severity,
+      category: args.evidence.finding.category,
+      evidenceState: args.evidence.finding.evidenceState ?? 'verified',
+      uncertaintyReason: args.evidence.finding.uncertaintyReason,
+      files: args.evidence.finding.files ?? [],
+      readManifest: args.evidence.finding.readManifest,
+      readLog: args.evidence.finding.readLog,
+      readDiagnostics: args.evidence.finding.readDiagnostics,
+    }) === digestCanonicalJson({
+      desc: candidate.desc,
+      severity: candidate.severity,
+      category: candidate.category,
+      evidenceState: candidate.evidenceState ?? 'verified',
+      uncertaintyReason: candidate.uncertaintyReason,
+      files: candidate.files ?? [],
+      readManifest: proposal.readManifest,
+      readLog: proposal.readLog,
+      readDiagnostics: proposal.readDiagnostics,
+    });
+  })();
+  const externalImportSealMatches = (() => {
+    if (!args.evidence) return true;
+    const bindingPath = join(runDirectory, 'evidence-binding.json');
+    const sealPath = join(runDirectory, 'evidence-binding.seal.json');
+    if (!existsSync(bindingPath) || !existsSync(sealPath)) return false;
+    try {
+      const external = JSON.parse(readFileSync(bindingPath, 'utf8')) as Record<string, unknown>;
+      const evidenceId = args.evidence.kind === 'pass' ? args.evidence.pass.id : args.evidence.finding.id;
+      return external.schemaVersion === 'lattice.managed_review_evidence_import.v1'
+        && external.runId === args.binding.runId
+        && external.receiptId === args.binding.receiptId
+        && external.storyId === args.storyId
+        && external.reviewRunId === args.reviewRunId
+        && external.lane === args.lane
+        && external.importedAt === args.binding.importedAt
+        && Array.isArray(external.importedIds)
+        && external.importedIds.includes(evidenceId);
+    } catch {
+      return false;
+    }
+  })();
+  const semanticDigestValid = proposal !== null
+    && proposalArtifacts.length === 1
+    && proposalArtifacts[0] === 'evidence-proposal.json'
+    && receipt.evidenceProposalDigest !== null
+    && receipt.evidenceProposalDigest === args.binding.proposalDigest
+    && observedProposalDigest === receipt.evidenceProposalDigest
+    && observedSpecDigest === receipt.specDigest
+    && observedEventJournalDigest === receipt.eventJournalDigest
+    && observedResultDigest === receipt.resultDigest
+    && externalImportSealMatches
+    && exactEvidenceMatches;
+  const receiptValid = receipt.receiptId === args.binding.receiptId
+    && receipt.terminalDigest === args.binding.terminalDigest
+    && observedTerminalDigest === args.binding.terminalDigest
+    && receipt.state === 'completed'
+    && receipt.replacementSafe === true
+    && receipt.processCleanup?.reaped === true
+    && receipt.processCleanup.residualProcessGroup === false;
+  const subjectMatches = proposal !== null
+    && proposal.providerAgent === args.binding.providerAgent
+    && args.binding.providerAgent === args.agent
+    && args.agent === args.lane
+    && proposal.lane === args.lane
+    && args.binding.lane === args.lane
+    && args.binding.reviewRunId === args.reviewRunId
+    && proposal.reviewRunId === args.reviewRunId
+    && runBinding.profile === 'managed_reviewer'
+    && runBinding.host === args.binding.providerHost
+    && runBinding.agentType === args.agent
+    && runBinding.lane === args.lane
+    && runBinding.reviewRunId === args.reviewRunId;
+  const reviewTupleMatches = runBinding.reviewBinding !== null
+    && runBinding.reviewBinding.headHash === args.expected.headHash
+    && runBinding.reviewBinding.materialHash === args.expected.materialHash
+    && runBinding.reviewBinding.storyFilesHash === args.expected.storyFilesHash
+    && runBinding.reviewBinding.promptHash === args.expected.promptHash
+    && runBinding.reviewBinding.envelopeId === args.expected.envelopeId
+    && args.binding.headHash === args.expected.headHash
+    && args.binding.materialHash === args.expected.materialHash
+    && args.binding.storyFilesHash === args.expected.storyFilesHash
+    && args.binding.promptHash === args.expected.promptHash
+    && args.binding.envelopeId === args.expected.envelopeId
+    && runBinding.promptDigest === args.expected.managedPromptDigest;
+  const storyMatches = proposal?.storyId === args.storyId
+    && runBinding.storyId === args.storyId;
+  const diagnostic = buildProofAdmissibilityDiagnostic({
+    artifactKind: 'managed-review-evidence',
+    artifactId: args.binding.receiptId,
+    consumer: 'REVIEW',
+    claim: 'review-pass',
+    mode: 'enforce',
+    enforcedConsumers: ['REVIEW'],
+    checks: {
+      schemaVersion: args.binding.schemaVersion,
+      strictShapeValid: shapeValid,
+      semanticDigestValid,
+      signatureOrReceiptBindingValid: receiptValid,
+      temporalAndMaterialBindingValid: subjectMatches && storyMatches && reviewTupleMatches,
+      subjectMatches,
+      storyMatches,
+      gatePhaseMatches: true,
+      producerBoundaryTrusted: receiptValid && subjectMatches && reviewTupleMatches,
+    },
+  });
+  const valid = diagnostic.allowed && !diagnostic.blocking;
+  return {
+    valid,
+    reason: valid ? 'managed_review_evidence_admissible' : diagnostic.reasons.join(','),
+    diagnostic,
+    receipt,
+    proposal,
+  };
+}
+
+export function createManagedReviewEvidenceBinding(args: {
+  root: string;
+  storyId: string;
+  providerAgent: string;
+  lane: string;
+  reviewRunId: string;
+  runId: string;
+  receiptId: string;
+  expected: ManagedReviewExpectedBinding;
+  importedAt?: string;
+}): { binding: ManagedReviewEvidenceBinding; verification: ManagedReviewEvidenceVerification } {
+  let receipt: ManagedHostRunReceipt | null = null;
+  try {
+    receipt = managedHostRunReceipt(args.root, args.runId);
+  } catch {
+    // The shared evaluator below classifies missing/non-terminal receipt input;
+    // the importer does not maintain a parallel allow/deny vocabulary.
+  }
+  const binding: ManagedReviewEvidenceBinding = {
+    schemaVersion: 'lattice.managed_review_evidence_binding.v1',
+    runId: args.runId,
+    receiptId: args.receiptId,
+    proposalDigest: receipt?.evidenceProposalDigest ?? '',
+    terminalDigest: receipt?.terminalDigest ?? '',
+    importedAt: args.importedAt ?? new Date().toISOString(),
+    providerAgent: args.providerAgent,
+    providerHost: args.expected.providerHost,
+    lane: args.lane,
+    reviewRunId: args.reviewRunId,
+    headHash: args.expected.headHash,
+    materialHash: args.expected.materialHash,
+    storyFilesHash: args.expected.storyFilesHash,
+    promptHash: args.expected.promptHash,
+    envelopeId: args.expected.envelopeId,
+    managedPromptDigest: args.expected.managedPromptDigest,
+  };
+  const verification = verifyManagedReviewEvidence({
+    root: args.root,
+    storyId: args.storyId,
+    agent: args.providerAgent,
+    lane: args.lane,
+    reviewRunId: args.reviewRunId,
+    binding,
+    expected: args.expected,
+  });
+  if (!verification.valid) {
+    throw new Error(`managed_review_evidence_import: ${verification.reason}`);
+  }
+  return { binding, verification };
+}
diff --git a/packages/main/src/core/native-review-attestation.ts b/packages/main/src/core/native-review-attestation.ts
new file mode 100644
index 0000000000..e6ed704d0b
--- /dev/null
+++ b/packages/main/src/core/native-review-attestation.ts
@@ -0,0 +1,218 @@
+import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
+import { dirname, join } from 'node:path';
+
+import {
+  signCanonical,
+  verifyCanonical,
+  type PrivateKeyBase64,
+  type PublicKeyBase64,
+  type SignatureBase64,
+} from './authority-signing.js';
+import { digestCanonicalJson } from './digest.js';
+import { resolveCanonicalRuntimeProjectRoot } from './runtime-artifact-registry.js';
+
+export const NATIVE_REVIEW_INVOCATION_ATTESTATION_SCHEMA =
+  'lattice.native_review_invocation_attestation.v1' as const;
+
+export interface NativeReviewBrokerRegistration {
+  brokerId: string;
+  adapterId: string;
+  host: 'codex' | 'claude';
+  publicKey: PublicKeyBase64;
+}
+
+export interface NativeReviewInvocationClaims {
+  schemaVersion: typeof NATIVE_REVIEW_INVOCATION_ATTESTATION_SCHEMA;
+  brokerId: string;
+  adapterId: string;
+  host: 'codex' | 'claude';
+  storyId: string;
+  agent: string;
+  lane: string;
+  reviewRunId: string;
+  writerSessionId: string;
+  dispatchPromptDigest: string;
+  dispatchBindingDigest: string;
+  hostRenderIdentityDigest: string;
+  invocationNonce: string;
+  issuedAt: string;
+  expiresAt: string;
+}
+
+export interface SignedNativeReviewInvocationAttestation extends NativeReviewInvocationClaims {
+  signature: SignatureBase64;
+}
+
+export type NativeReviewInvocationExpected = Omit<
+  NativeReviewInvocationClaims,
+  'schemaVersion' | 'brokerId' | 'adapterId' | 'invocationNonce' | 'issuedAt' | 'expiresAt'
+>;
+
+export type NativeReviewInvocationVerification =
+  | { ok: true; broker: NativeReviewBrokerRegistration; attestationDigest: string }
+  | { ok: false; reason: string };
+
+function unsignedAttestation(
+  attestation: SignedNativeReviewInvocationAttestation,
+): NativeReviewInvocationClaims {
+  const { signature: _signature, ...claims } = attestation;
+  return claims;
+}
+
+function nonEmpty(value: unknown): value is string {
+  return typeof value === 'string' && value.trim().length > 0;
+}
+
+function validDigest(value: unknown): value is string {
+  return typeof value === 'string' && /^(?:sha256:)?[a-f0-9]{64}$/.test(value);
+}
+
+function validClaims(claims: NativeReviewInvocationClaims): boolean {
+  return claims.schemaVersion === NATIVE_REVIEW_INVOCATION_ATTESTATION_SCHEMA
+    && /^[A-Za-z0-9][A-Za-z0-9._-]{2,127}$/.test(claims.brokerId)
+    && /^[A-Za-z0-9][A-Za-z0-9._-]{2,127}$/.test(claims.adapterId)
+    && (claims.host === 'codex' || claims.host === 'claude')
+    && nonEmpty(claims.storyId)
+    && nonEmpty(claims.agent)
+    && nonEmpty(claims.lane)
+    && nonEmpty(claims.reviewRunId)
+    && nonEmpty(claims.writerSessionId)
+    && validDigest(claims.dispatchPromptDigest)
+    && validDigest(claims.dispatchBindingDigest)
+    && validDigest(claims.hostRenderIdentityDigest)
+    && /^[A-Za-z0-9][A-Za-z0-9._-]{15,127}$/.test(claims.invocationNonce)
+    && Number.isFinite(Date.parse(claims.issuedAt))
+    && Number.isFinite(Date.parse(claims.expiresAt));
+}
+
+/**
+ * Host-adapter SDK helper. Lattice exposes no CLI issuer and stores no broker
+ * private key; only a separately registered host broker can produce a trusted
+ * signature. Calling this helper with a self-generated key remains untrusted.
+ */
+export function signNativeReviewInvocationAttestation(
+  claims: NativeReviewInvocationClaims,
+  privateKey: PrivateKeyBase64,
+): SignedNativeReviewInvocationAttestation {
+  return { ...claims, signature: signCanonical(claims, privateKey) };
+}
+
+export function verifyNativeReviewInvocationAttestation(args: {
+  attestation: SignedNativeReviewInvocationAttestation;
+  trustedBrokers: readonly NativeReviewBrokerRegistration[];
+  expected: NativeReviewInvocationExpected;
+  now?: number;
+  requireFresh?: boolean;
+}): NativeReviewInvocationVerification {
+  const claims = unsignedAttestation(args.attestation);
+  if (!validClaims(claims)) return { ok: false, reason: 'native invocation attestation claims are malformed' };
+  const matchingBrokers = args.trustedBrokers.filter(candidate =>
+    candidate.brokerId === claims.brokerId
+    && candidate.adapterId === claims.adapterId
+    && candidate.host === claims.host);
+  if (matchingBrokers.length !== 1) {
+    return { ok: false, reason: 'native invocation attestation issuer is not one uniquely registered host broker' };
+  }
+  const broker = matchingBrokers[0]!;
+  if (!verifyCanonical(claims, args.attestation.signature, broker.publicKey)) {
+    return { ok: false, reason: 'native invocation attestation signature is invalid' };
+  }
+  const now = args.now ?? Date.now();
+  const issuedAt = Date.parse(claims.issuedAt);
+  const expiresAt = Date.parse(claims.expiresAt);
+  if (issuedAt > now + 5_000 || expiresAt <= issuedAt || expiresAt - issuedAt > 120_000
+    || ((args.requireFresh ?? true) && expiresAt < now)) {
+    return { ok: false, reason: 'native invocation attestation is expired or outside the bounded issuance window' };
+  }
+  for (const field of [
+    'host',
+    'storyId',
+    'agent',
+    'lane',
+    'reviewRunId',
+    'writerSessionId',
+    'dispatchPromptDigest',
+    'dispatchBindingDigest',
+    'hostRenderIdentityDigest',
+  ] as const) {
+    if (claims[field] !== args.expected[field]) {
+      return { ok: false, reason: `native invocation attestation ${field} does not match the exact review invocation` };
+    }
+  }
+  return {
+    ok: true,
+    broker,
+    attestationDigest: `sha256:${digestCanonicalJson(args.attestation)}`,
+  };
+}
+
+function consumptionPath(projectRoot: string, attestation: SignedNativeReviewInvocationAttestation): string {
+  const canonicalRoot = resolveCanonicalRuntimeProjectRoot(projectRoot);
+  return join(
+    canonicalRoot,
+    '.lattice',
+    'runtime',
+    'native-review-invocations',
+    attestation.brokerId,
+    `${attestation.invocationNonce}.json`,
+  );
+}
+
+/** Verify and atomically burn the broker nonce exactly once. */
+export function consumeNativeReviewInvocationAttestation(args: {
+  projectRoot: string;
+  attestation: SignedNativeReviewInvocationAttestation;
+  trustedBrokers: readonly NativeReviewBrokerRegistration[];
+  expected: NativeReviewInvocationExpected;
+  now?: number;
+}): NativeReviewInvocationVerification {
+  const verified = verifyNativeReviewInvocationAttestation(args);
+  if (!verified.ok) return verified;
+  const path = consumptionPath(args.projectRoot, args.attestation);
+  mkdirSync(dirname(path), { recursive: true, mode: 0o700 });
+  try {
+    writeFileSync(path, `${JSON.stringify({
+      schemaVersion: 'lattice.native_review_invocation_consumption.v1',
+      brokerId: args.attestation.brokerId,
+      invocationNonce: args.attestation.invocationNonce,
+      attestationDigest: verified.attestationDigest,
+      consumedAt: new Date(args.now ?? Date.now()).toISOString(),
+    })}\n`, { encoding: 'utf8', mode: 0o600, flag: 'wx' });
+  } catch (error) {
+    if ((error as NodeJS.ErrnoException).code === 'EEXIST') {
+      return { ok: false, reason: 'native invocation attestation nonce was already consumed' };
+    }
+    throw error;
+  }
+  return verified;
+}
+
+/**
+ * Read the capability only from a broker-supplied inherited descriptor. Inline
+ * environment tokens are deliberately unsupported because they are forgeable
+ * and commonly inherited by raw provider children.
+ */
+export function readNativeReviewInvocationAttestationFromFd(
+  env: NodeJS.ProcessEnv = process.env,
+): SignedNativeReviewInvocationAttestation | null {
+  const rawFd = env.LATTICE_NATIVE_REVIEW_ATTESTATION_FD?.trim();
+  if (!rawFd) return null;
+  const fd = Number(rawFd);
+  if (!Number.isInteger(fd) || fd < 3 || fd > 255) {
+    throw new Error('native invocation attestation fd must be an inherited descriptor between 3 and 255');
+  }
+  const raw = readFileSync(fd, 'utf8');
+  if (Buffer.byteLength(raw, 'utf8') > 64 * 1024) {
+    throw new Error('native invocation attestation exceeds 64 KiB');
+  }
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(raw);
+  } catch {
+    throw new Error('native invocation attestation fd does not contain JSON');
+  }
+  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
+    throw new Error('native invocation attestation fd does not contain an object');
+  }
+  return parsed as SignedNativeReviewInvocationAttestation;
+}
diff --git a/packages/main/src/core/native-review-evidence.ts b/packages/main/src/core/native-review-evidence.ts
new file mode 100644
index 0000000000..68193c9db5
--- /dev/null
+++ b/packages/main/src/core/native-review-evidence.ts
@@ -0,0 +1,273 @@
+import { createHash } from 'node:crypto';
+import { execFileSync } from 'node:child_process';
+import { basename } from 'node:path';
+
+import type { SessionIdentity } from './owner-session.js';
+import type { PromptHost } from './prompt-registry.js';
+import type { NativeReviewEvidenceBinding } from './types.js';
+import { digestCanonicalJson } from './digest.js';
+import { loadConfig } from './config.js';
+import {
+  consumeNativeReviewInvocationAttestation,
+  readNativeReviewInvocationAttestationFromFd,
+  verifyNativeReviewInvocationAttestation,
+  type NativeReviewBrokerRegistration,
+  type SignedNativeReviewInvocationAttestation,
+} from './native-review-attestation.js';
+
+export interface NativeReviewDispatchAuthority {
+  hostRenderHost: PromptHost;
+  dispatchPromptDigest: string;
+  hostRenderIdentityDigest: string;
+  dispatchBindingDigest: string;
+}
+
+function promptHostForSession(identity: SessionIdentity): PromptHost | null {
+  if (identity.hostProvider === 'codex') return 'codex';
+  if (identity.hostProvider === 'claude-code') return 'claude';
+  return null;
+}
+
+export interface NativeHostProcessObservation {
+  host: PromptHost;
+  processLineageDigest: string;
+  providerFamilies?: PromptHost[];
+  mixedProviderFamilies?: boolean;
+}
+
+export interface NativeHostProcessLineageRow {
+  pid: number;
+  ppid: number;
+  comm: string;
+  command: string;
+}
+
+function providerForProcess(comm: string, command: string): PromptHost | null {
+  const executableNames = [basename(comm), basename(command.trim().split(/\s+/, 1)[0] ?? '')]
+    .map(value => value.toLowerCase());
+  if (executableNames.some(value => value === 'codex' || value.startsWith('codex-'))) return 'codex';
+  if (executableNames.some(value => value === 'claude' || value === 'claude-code' || value.startsWith('claude-'))) return 'claude';
+  return null;
+}
+
+function commandDigest(command: string): string {
+  return `sha256:${createHash('sha256').update(command, 'utf8').digest('hex')}`;
+}
+
+/** Classify every visible provider family, retaining nearest-first order. */
+export function classifyNativeHostProcessLineage(
+  rows: readonly NativeHostProcessLineageRow[],
+): NativeHostProcessObservation {
+  const lineage = rows.map(row => ({
+    pid: row.pid,
+    ppid: row.ppid,
+    comm: basename(row.comm),
+    commandDigest: commandDigest(row.command),
+  }));
+  const providerFamilies: PromptHost[] = [];
+  for (const row of rows) {
+    const provider = providerForProcess(row.comm, row.command);
+    if (provider && !providerFamilies.includes(provider)) providerFamilies.push(provider);
+  }
+  const host = providerFamilies[0];
+  if (!host) throw new Error('native process lineage contains no Codex/Claude provider family');
+  return {
+    host,
+    providerFamilies,
+    mixedProviderFamilies: providerFamilies.length > 1,
+    processLineageDigest: `sha256:${digestCanonicalJson({
+      schemaVersion: 'lattice.native_review_process_lineage.v2',
+      host,
+      providerFamilies,
+      lineage,
+    })}`,
+  };
+}
+
+/** Inspect the complete visible Codex/Claude ancestry; inherited env is not provenance. */
+export function observeNativeHostProcess(startPid = process.ppid): NativeHostProcessObservation | null {
+  if (process.platform === 'win32') return null;
+  let pid = startPid;
+  const lineage: NativeHostProcessLineageRow[] = [];
+  const seen = new Set<number>();
+  let complete = false;
+  for (let depth = 0; depth < 32 && Number.isInteger(pid) && pid > 1 && !seen.has(pid); depth += 1) {
+    seen.add(pid);
+    let raw: string;
+    try {
+      raw = execFileSync('ps', ['-o', 'ppid=', '-o', 'comm=', '-o', 'command=', '-p', String(pid)], {
+        encoding: 'utf8',
+        timeout: 1_000,
+        stdio: ['ignore', 'pipe', 'ignore'],
+      }).trim();
+    } catch {
+      return null;
+    }
+    const match = raw.match(/^\s*(\d+)\s+(\S+)\s+(.+)$/s);
+    if (!match) return null;
+    const ppid = Number(match[1]);
+    const comm = match[2] ?? '';
+    const command = match[3] ?? '';
+    lineage.push({ pid, ppid, comm, command });
+    const classified = lineage.some(row => providerForProcess(row.comm, row.command))
+      ? classifyNativeHostProcessLineage(lineage)
+      : null;
+    if (classified?.mixedProviderFamilies) return classified;
+    if (ppid <= 1) {
+      complete = true;
+      break;
+    }
+    pid = ppid;
+  }
+  return complete && lineage.some(row => providerForProcess(row.comm, row.command))
+    ? classifyNativeHostProcessLineage(lineage)
+    : null;
+}
+
+function trustedNativeReviewBrokers(projectRoot: string): NativeReviewBrokerRegistration[] {
+  return (loadConfig(projectRoot).nativeReviewInvocation?.brokers ?? []).filter(
+    (broker): broker is NativeReviewBrokerRegistration =>
+      typeof broker.brokerId === 'string'
+      && typeof broker.adapterId === 'string'
+      && (broker.host === 'codex' || broker.host === 'claude')
+      && typeof broker.publicKey === 'string',
+  );
+}
+
+/**
+ * Consume a one-shot invocation attestation signed by a separately registered
+ * host adapter/broker. OS ancestry is only corroboration: an unavailable
+ * process table does not negate a valid broker signature, while any visible
+ * mixed Codex/Claude lineage is an unconditional cross-provider veto.
+ */
+export function issueNativeReviewEvidenceBinding(args: {
+  projectRoot: string;
+  storyId: string;
+  agent: string;
+  lane: string;
+  reviewRunId: string;
+  identity: SessionIdentity;
+  dispatch: NativeReviewDispatchAuthority;
+  attestation?: SignedNativeReviewInvocationAttestation;
+  trustedBrokers?: readonly NativeReviewBrokerRegistration[];
+  observeProcess?: () => NativeHostProcessObservation | null;
+}): NativeReviewEvidenceBinding {
+  const nativeHost = promptHostForSession(args.identity);
+  if (nativeHost === null || !args.identity.nativeSessionRef) {
+    throw new Error('native reviewer authority requires a supported host-adapter identity (codex or claude-code)');
+  }
+  if (nativeHost !== args.dispatch.hostRenderHost) {
+    throw new Error(
+      `cross-provider direct reviewer evidence is advisory-only: current environment host=${nativeHost}, `
+      + `signed dispatch host=${args.dispatch.hostRenderHost}; use cross_host_review/host_run managed reviewer evidence`,
+    );
+  }
+  const attestation = args.attestation ?? readNativeReviewInvocationAttestationFromFd();
+  if (!attestation) {
+    throw new Error(
+      'native reviewer authority requires a registered host-adapter invocation attestation; '
+      + 'without an adapter broker, direct evidence is advisory-only and formal review must use managed reviewer evidence',
+    );
+  }
+  const trustedBrokers = args.trustedBrokers ?? trustedNativeReviewBrokers(args.projectRoot);
+  const verified = consumeNativeReviewInvocationAttestation({
+    projectRoot: args.projectRoot,
+    attestation,
+    trustedBrokers,
+    expected: {
+      host: nativeHost,
+      storyId: args.storyId,
+      agent: args.agent,
+      lane: args.lane,
+      reviewRunId: args.reviewRunId,
+      writerSessionId: args.identity.sessionId,
+      dispatchPromptDigest: args.dispatch.dispatchPromptDigest,
+      dispatchBindingDigest: args.dispatch.dispatchBindingDigest,
+      hostRenderIdentityDigest: args.dispatch.hostRenderIdentityDigest,
+    },
